<script setup lang="ts">
const started = ref(false); const submitted = ref(false); const current = ref(0); const answers = ref<Record<number, string>>({}); const seconds = ref(600); let timer: ReturnType<typeof setInterval> | undefined;
const questions = [{ prompt: 'What is the woman mainly discussing?', options: ['A new schedule', 'A product return', 'A team meeting', 'A travel plan'], answer: 'A new schedule' }, { prompt: 'When will the report be ready?', options: ['This afternoon', 'Next Monday', 'At the front desk', 'With the client'], answer: 'Next Monday' }, { prompt: 'What should the listener do next?', options: ['Send an email', 'Check the invoice', 'Book a room', 'Call the manager'], answer: 'Send an email' }];
const active = computed(() => questions[current.value]); const answered = computed(() => Object.keys(answers.value).length); const score = computed(() => questions.reduce((total, q, i) => total + (answers.value[i] === q.answer ? 1 : 0), 0)); const clock = computed(() => `${String(Math.floor(seconds.value / 60)).padStart(2, '0')}:${String(seconds.value % 60).padStart(2, '0')}`);
function start() { started.value = true; timer = setInterval(() => { if (seconds.value > 0) seconds.value -= 1; else submit(); }, 1000); }
function submit() { submitted.value = true; if (timer) clearInterval(timer); }
onUnmounted(() => { if (timer) clearInterval(timer); });
</script>

<template>
  <div class="page-enter space-y-6"><section class="rounded-[26px] bg-ink p-6 text-white shadow-float sm:p-9"><div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-xs font-extrabold tracking-[0.18em] text-bean">MOCK TEST</p><h1 class="mt-3 text-4xl font-extrabold tracking-[-0.06em] sm:text-5xl">Một đề nhỏ, một bước tiến.</h1><p class="mt-3 max-w-xl text-sm leading-6 text-white/65">Làm thử trong 10 phút. Câu trả lời được giữ ngay trên trình duyệt để bạn tập trung vào nhịp làm bài.</p></div><div v-if="started && !submitted" class="rounded-2xl bg-white/10 px-4 py-3 text-right"><p class="text-[11px] text-white/55">Còn lại</p><p class="mt-1 text-xl font-extrabold">{{ clock }}</p></div></div></section><section v-if="!started" class="mx-auto max-w-2xl rounded-[22px] border border-line bg-white p-6 text-center shadow-soft sm:p-10"><span class="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-iris/10 text-2xl text-iris">▥</span><h2 class="mt-5 text-2xl font-extrabold tracking-[-0.04em]">Mini test · Listening & Reading</h2><p class="mx-auto mt-3 max-w-md text-sm leading-6 text-ink/55">3 câu mẫu để làm nóng. Khi kho đề được nạp, trang này sẽ tự chuyển sang bộ câu hỏi thật.</p><button class="mt-7 rounded-xl bg-ink px-5 py-3 text-xs font-extrabold text-white transition hover:bg-iris focus-ring" @click="start">Bắt đầu test</button></section><section v-else-if="!submitted" class="mx-auto max-w-3xl rounded-[22px] border border-line bg-white p-5 shadow-soft sm:p-8"><div class="flex items-center justify-between text-xs font-extrabold text-ink/45"><span>CÂU {{ current + 1 }} / {{ questions.length }}</span><span>{{ answered }} đã trả lời</span></div><h2 class="mt-7 text-2xl font-extrabold leading-tight tracking-[-0.04em]">{{ active.prompt }}</h2><div class="mt-7 space-y-3"><label v-for="option in active.options" :key="option" :class="['flex cursor-pointer items-center gap-3 rounded-2xl border p-4 transition', answers[current] === option ? 'border-iris bg-iris/5' : 'border-line hover:border-iris/40']"><input v-model="answers[current]" class="sr-only" type="radio" :name="`q-${current}`" :value="option"><span class="grid h-8 w-8 place-items-center rounded-lg bg-paper text-xs font-extrabold text-ink/60">{{ option.slice(0, 1) }}</span><span class="text-sm font-bold">{{ option }}</span></label></div><div class="mt-8 flex flex-wrap justify-between gap-3"><button class="rounded-xl border border-line px-4 py-3 text-xs font-extrabold transition hover:bg-paper disabled:opacity-40 focus-ring" :disabled="current === 0" @click="current -= 1">Câu trước</button><button v-if="current < questions.length - 1" class="rounded-xl bg-ink px-4 py-3 text-xs font-extrabold text-white transition hover:bg-iris focus-ring" @click="current += 1">Câu tiếp</button><button v-else class="rounded-xl bg-iris px-4 py-3 text-xs font-extrabold text-white transition hover:bg-ink focus-ring" @click="submit">Nộp bài</button></div></section><section v-else class="mx-auto max-w-2xl rounded-[22px] border border-line bg-white p-6 text-center shadow-soft sm:p-10"><p class="text-xs font-extrabold tracking-[0.18em] text-iris">KẾT QUẢ</p><p class="mt-5 text-6xl font-extrabold tracking-[-0.08em] text-ink">{{ score }}<span class="text-2xl text-ink/30"> / {{ questions.length }}</span></p><p class="mt-3 text-sm text-ink/55">Bạn đã hoàn thành mini test. Thử lại để luyện tốc độ và độ chắc tay.</p><button class="mt-7 rounded-xl bg-ink px-5 py-3 text-xs font-extrabold text-white transition hover:bg-iris focus-ring" @click="started = false; submitted = false; current = 0; answers = {}; seconds = 600">Làm lại</button></section></div>
</template>
